function script:qs_intro {
  q_say 'A storm rolled in last night and the lighthouse lamp went dark. Mara, the old keeper, has gone to the mainland for parts, and she left you in charge. Ships are out there tonight.

You''re standing in the lighthouse grounds at a terminal. Here, places are folders, and notes, maps and treasures are files.

First, find out where you are. Type Get-Location and press Enter.'
}

function script:qs_layout {
  $null = $null
}

function script:qs_processes {
  $null = $null
}

function script:qs_fire([string]$on, [string]$key) {
  switch -Exact ("${on}:$key") {
    'enter:cottage' {
      if ((q_trigger_ready 0 $false)) {
        q_trigger_mark 0
        q_say 'The cottage smells of salt and old books.'
      }
    }
    'enter:shore' {
      if ((q_trigger_ready 1 $false)) {
        q_trigger_mark 1
        q_say 'Waves hiss on the sand. The storm left things behind.'
      }
    }
    'enter:tower/stairs/landing/lantern-room' {
      if ((q_trigger_ready 2 $false)) {
        q_trigger_mark 2
        q_say 'You made it to the top. The wind whistles around the glass.'
      }
    }
    'read:cottage/kitchen/cupboard/matches.txt' {
      if ((q_trigger_ready 3 $false)) {
        q_trigger_mark 3
        q_say 'Now climb the tower: the lamp is at the very top.'
      }
    }
    'read:tower/stairs/landing/lantern-room/lamp.txt' {
      if ((q_trigger_ready 4 $true) -and (-not (q_read 'cottage/kitchen/cupboard/matches.txt'))) {
        q_trigger_mark 4
        q_say 'You have nothing to light it with. Mara''s diary says where the matches are.'
      }
      if ((q_trigger_ready 5 $false) -and (q_read 'cottage/kitchen/cupboard/matches.txt')) {
        q_trigger_mark 5
        q_say 'You strike a match and touch it to the wick. The flame catches, the great lens begins to turn, and a beam of light sweeps across the water. Out at sea, three ships turn for the harbor.'
        q_flag_set 'lit'
      }
    }
  }
}

