      return [bool](q_flag 'lit')
    }
  }
  return $false
}

function script:qs_goal_teach([string]$id) {
  switch -Exact ($id) {
    'where' {
      q_say 'Get-Location tells you the folder you are in right now. The answer is a path: the drive (C:), then the folders down to you, each separated by a \. (pwd works too: it is a nickname, an alias, for Get-Location.)'
    }
    'look' {
      q_say 'Get-ChildItem lists what''s in the folder you''re in: folders (places you can go, marked d in the Mode column) and files (things you can read). ls and dir work too: they are aliases for Get-ChildItem.'
    }
    'welcome' {
      q_say 'Get-Content prints a file''s text on the screen. Give it the file''s name: Get-Content welcome.txt. Tip: type just "Get-Content we" and press Tab.'
    }
    'cottage' {
      q_say 'Set-Location moves you into a folder ("change directory"). Watch the prompt: it changes to show where you are now.'
    }
    'diary' {
      q_say 'A folder can hold more folders. Go into the bedroom with Set-Location bedroom, look with Get-ChildItem, and read with Get-Content.'
    }
    'compass' {
      q_say 'The diary says the compass is in the drawer by the bed. The drawer is a folder inside the bedroom.'
    }
    'matches' {
      q_say 'Two dots, .., mean "the folder I''m inside of": one step back up. Join steps with \: from the drawer, ..\.. goes up two folders to the cottage, and ..\..\kitchen\cupboard goes up two and then down into the kitchen''s cupboard, all in one command.'
    }
    'pearl' {
      q_say '~ means your home folder, so ~\lighthouse\shore works from anywhere. On the shore, Get-ChildItem does not show everything: names that start with a dot are hidden. Get-ChildItem -Force shows them.'
    }
    'climb' {
      q_say 'You can go through several folders in one go: Set-Location ..\tower\stairs\landing\lantern-room. That''s a lot to type, so type a few letters of each name and press Tab: the terminal fills in the rest.'
    }
    'history' {
      q_say 'Get-History lists every command you have typed, numbered. The up arrow brings back the last one, so you never type the same thing twice.'
    }
    'lamp' {
      q_say 'The lamp is a file here. Read it: with the matches in your pocket, that''s all it takes.'
    }
  }
}

