function script:qs_goal_solution([string]$id) {
  switch -Exact ($id) {
    'where' {
      return ,@('Get-Location')
    }
    'look' {
      return ,@('Get-ChildItem')
    }
    'welcome' {
      return ,@('Get-Content welcome.txt')
    }
    'cottage' {
      return ,@('Set-Location cottage')
    }
    'diary' {
      return ,@('Set-Location bedroom', 'Get-Content diary.txt')
    }
    'compass' {
      return ,@('Set-Location drawer', 'Get-Content brass-compass.txt')
    }
    'matches' {
      return ,@('Set-Location ..\..\kitchen\cupboard', 'Get-Content matches.txt')
    }
    'pearl' {
      return ,@('Set-Location ~\lighthouse\shore', 'Get-ChildItem -Force', 'Get-Content .crab-shell\pearl.txt')
    }
    'climb' {
      return ,@('Set-Location ..\tower\stairs\landing\lantern-room')
    }
    'history' {
      return ,@('Get-History')
    }
    'lamp' {
      return ,@('Get-Content lamp.txt')
    }
  }
}

function script:qs_finish_when {
  return [bool](q_flag 'lit')
}

function script:qs_finish_text {
  q_say 'The lighthouse shines again, and the ships come home safe. Mara will be proud.

You learned to ask where you are (Get-Location), look around (Get-ChildItem), move (Set-Location and Set-Location ..), read (Get-Content), find hidden things (Get-ChildItem -Force) and look back at what you did (Get-History). Those are the commands you''ll use most, every day.'
}

function script:qs_object([string]$obj, [string[]]$argv) {
  return 1
}
